def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the background as the most common color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Full uniform rows and columns of a non-background color are dividers.
    sep_rows = [
        r for r in range(h)
        if grid[r][0] != bg and all(v == grid[r][0] for v in grid[r])
    ]
    sep_cols = [
        c for c in range(w)
        if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))
    ]

    def segments(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)

    # Gather the pattern in tile-relative coordinates, using marks from every
    # tile (the first tile may contain no marks).
    pattern = {}
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] != bg:
                        pattern[(r - r0, c - c0)] = grid[r][c]

    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            for (dr, dc), color in pattern.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color

    return out
